import com.vaadin.flow.component.button.Button;
import com.vaadin.flow.component.html.H1;
import com.vaadin.flow.component.html.ListItem;
import com.vaadin.flow.component.html.Span;
import com.vaadin.flow.component.html.UnorderedList;
import com.vaadin.flow.component.orderedlayout.VerticalLayout;
import com.vaadin.flow.component.textfield.TextField;
import com.vaadin.flow.router.Route;
import java.util.ArrayList;
import java.util.List;

@Route(layout = MainLayout.class)
public class MainView extends VerticalLayout {

    private final List<String> items = new ArrayList<>();
    private final UnorderedList list = new UnorderedList();
    private final Span countSpan = new Span("Items: 0");
    private final TextField itemField = new TextField();

    public MainView() {
        setSpacing(true);
        setPadding(true);

        H1 heading = new H1("Items");
        add(heading);

        itemField.setLabel("Item");
        itemField.setPlaceholder("Enter item");
        add(itemField);

        Button addButton = new Button("Add", event -> addItem());
        Button clearButton = new Button("Clear", event -> clearItems());
        add(addButton, clearButton);

        add(list);
        add(countSpan);
    }

    private void addItem() {
        String value = itemField.getValue().trim();
        if (value.isEmpty()) {
            itemField.setInvalid(true);
            return;
        }
        itemField.setInvalid(false);
        items.add(value);
        itemField.setValue("");
        updateList();
    }

    private void clearItems() {
        items.clear();
        itemField.setInvalid(false);
        updateList();
    }

    private void updateList() {
        list.removeAll();
        for (String item : items) {
            list.add(new ListItem(item));
        }
        countSpan.setText("Items: " + items.size());
    }
